// Icon renders a lucide icon as inline SVG; class carries Meetily's size utility, e.g. "w-4 h-4".
func Icon(name string, class ...string) template.HTML {
	inner, ok := icons[name]
	if !ok {
		panic("unknown icon " + name)
	}
	cls := "lucide lucide-" + name
	if len(class) > 0 {
		cls += " " + strings.Join(class, " ")
	}
	return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="` + template.HTMLEscapeString(cls) + `" aria-hidden="true">` + inner + `</svg>`)
}
